  final entries = <LedgerEntry>[];
  for (final record in visiblePath) {
    final entry = _entryFor(record, seqs, cache);
    if (entry != null) entries.add(entry);
  }
  return ContextLedger._(entries, _pairGroups(visiblePath));
}

