  final buf = StringBuffer();
  for (var i = 0; i < count; i++) {
    buf.write('tok ');
    for (var c = 0; c < 40; c++) {
      buf.write(alphabet[rng.nextInt(alphabet.length)]);
    }
    buf.write(' end of line item number $i ');
