      'the quick brown fox jumps over a lazy dog while reviewing logs '
      'and writing summaries of the deployed release notes today ';
  final buf = StringBuffer();
  while (buf.length < size) {
    buf.write(words);
  }
  return buf.toString().substring(0, size);
}

